-- Banco curricular v12 (original): 5 unidades, 17 conjuntos, 170 prácticas, 60 preguntas de pruebas de unidad y 40 de ensayo.
-- Fuente curricular: temario Mineduc de VALIDACION DE ESTUDIOS 4 básico (Matemática OA1,3,5,6,7,8,9,13,14,17,18,22,23,27).
-- El ensayo de 40 reactivos es una simulación de demostración; NO es un instrumento SIMCE oficial.
UPDATE pregunta SET activa = FALSE WHERE codigo IS NULL OR codigo NOT LIKE 'V12-%';
UPDATE conjunto SET activo = FALSE WHERE codigo LIKE 'NUM-N%';
UPDATE nivel SET orden = CASE codigo WHEN 'NUM-N1' THEN 101 WHEN 'NUM-N2' THEN 102 END WHERE codigo IN ('NUM-N1','NUM-N2') AND orden IN (1,2);
