UPDATE estudiante_posicion ep SET conjunto_id=(SELECT id FROM conjunto WHERE codigo='U1-C01'), punto_partida_id=(SELECT id FROM conjunto WHERE codigo='U1-C01'), cierre_nivel_pendiente=FALSE, requiere_profesor=FALSE, actualizado_en=now() WHERE EXISTS (SELECT 1 FROM conjunto c WHERE c.id=ep.conjunto_id AND NOT c.activo);
